export const MEDICATION_IDS = Object.keys(MEDICATION_DATA);

/** Medications grouped by class for the left panel, sorted alphabetically within each class. */
export const MEDICATION_CLASS_ORDER = [
  'Antiplatelet', 'Anticoagulant', 'Thrombolytic', 'Nitrate', 'Beta-blocker', 'Calcium channel blocker',
  'Antiarrhythmic', 'Cardiac glycoside', 'Anticholinergic', 'Vasopressor', 'Vasopressor / Inotrope', 'Inotrope', 'Inotrope / Chronotrope',
  'Vasodilator', 'Diuretic', 'ACE inhibitor', 'ARNI', 'Mineralocorticoid receptor antagonist', 'SGLT2 inhibitor', 'Statin',
  'Sinus node inhibitor', 'Cardiac myosin inhibitor', 'Electrolyte', 'Anti-inflammatory', 'Opioid analgesic',
];

export const MEDICATIONS_BY_CLASS: { cat: string; items: { id: string; name: string }[] }[] = MEDICATION_CLASS_ORDER
  .map((cat) => ({
    cat,
    items: MEDICATION_IDS
      .filter((id) => MEDICATION_DATA[id].drugClass === cat)
      .map((id) => ({ id, name: MEDICATION_DATA[id].name }))
      .sort((a, b) => a.name.localeCompare(b.name)),
  }))
  .filter((g) => g.items.length > 0);

/** Tab name → data field for the medication info panel. */
export const MEDICATION_TAB_FIELDS: Record<string, keyof MedicationInfo> = {
  'overview': 'overview',
  'mechanism': 'mechanism',
  'indications': 'indications',
  'acls': 'aclsUses',
  'dosing': 'dosing',
  'contraindications': 'contraindications',
  'side-effects': 'sideEffects',
  'ecg': 'ecgEffects',
  'hemodynamics': 'hemodynamicEffects',
  'monitoring': 'monitoring',
  'interactions': 'interactions',
  'teaching': 'teaching',
};

export function searchMedications(query: string): string[] {
  const q = query.trim().toLowerCase();
  if (!q) return MEDICATION_IDS;
  return MEDICATION_IDS.filter((id) => {
    const m = MEDICATION_DATA[id];
    return m.name.toLowerCase().includes(q)
      || m.brandNames.some((b) => b.toLowerCase().includes(q))
      || m.drugClass.toLowerCase().includes(q)
      || m.subclass.toLowerCase().includes(q);
  });
}
